/**
 * Batch 1 — ~100 verified India Quiz questions.
 *
 * Every question is fact-checked against reliable sources:
 *   - Government of India official websites
 *   - Constitutional texts
 *   - ISRO, RBI, Election Commission
 *   - UNESCO, IUCN
 *   - Sports governing bodies (ICC, FIH, IOC)
 *   - Encyclopaedia Britannica, National Museum
 *
 * Each question has:
 *   - A unique slug (stable ID)
 *   - Exactly 4 options with one correct answer
 *   - A verified explanation
 *   - A source reference
 *   - A difficulty level (easy/medium/hard)
 *
 * Run via: bunx tsx scripts/import-batch-1.ts
 */
import { db } from '@/lib/db';
import { checkDuplicate } from '@/lib/quiz/duplicate-detector';

interface Q {
  slug: string;
  categoryId: string;
  text: string;
  options: [string, string, string, string];
  correctIndex: number;
  explanation: string;
  source: string;
  difficulty: 'easy' | 'medium' | 'hard';
}

const BATCH: Q[] = [
  // ═══ cat-gk: General Knowledge (10 new) ═══
  { slug: 'gk-national-emblem-origin', categoryId: 'cat-gk', text: 'The national emblem of India is an adaptation of which historical sculpture?', options: ['Sanchi Stupa', 'Lion Capital of Ashoka at Sarnath', 'Iron Pillar of Delhi', 'Gate of Sanchi'], correctIndex: 1, explanation: 'The national emblem is adapted from the Lion Capital of Ashoka at Sarnath, erected by Emperor Ashoka in the 3rd century BCE. It was adopted on 26 January 1950.', source: 'Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'gk-national-calender', categoryId: 'cat-gk', text: 'Which calendar was adopted as the national calendar of India in 1957?', options: ['Gregorian calendar', 'Saka calendar', 'Hijri calendar', 'Vikram Samvat'], correctIndex: 1, explanation: 'The Saka calendar was adopted as the national calendar on 22 March 1957 (Chaitra 1, 1879 Saka). The Gregorian calendar is also used for official purposes.', source: 'Government of India national symbols', difficulty: 'hard' },
  { slug: 'gk-national-anthem-duration', categoryId: 'cat-gk', text: 'What is the approximate duration of the full version of the Indian national anthem "Jana Gana Mana"?', options: ['30 seconds', '52 seconds', '1 minute', '2 minutes'], correctIndex: 1, explanation: 'The full version of "Jana Gana Mana" takes approximately 52 seconds to play. A shorter version of about 20 seconds is used on certain occasions.', source: 'Government of India national symbols', difficulty: 'medium' },
  { slug: 'gk-national-song', categoryId: 'cat-gk', text: 'Which song is recognized as the national song of India?', options: ['Saare Jahan se Achha', 'Vande Mataram', 'Jana Gana Mana', 'Sare Jahan se Accha'], correctIndex: 1, explanation: '"Vande Mataram", composed by Bankim Chandra Chattopadhyay, is the national song of India. It was adopted on 24 January 1950.', source: 'Government of India national symbols', difficulty: 'easy' },
  { slug: 'gk-states-reorganization-act', categoryId: 'cat-gk', text: 'The States Reorganisation Act of 1956 reorganized Indian states primarily on what basis?', options: ['Religion', 'Language', 'Geography', 'Population'], correctIndex: 1, explanation: 'The States Reorganisation Act of 1956 reorganized states along linguistic lines, creating 14 states and 6 union territories.', source: 'Ministry of Home Affairs', difficulty: 'medium' },
  { slug: 'gk-largest-population-state', categoryId: 'cat-gk', text: 'As of the 2011 Census, which was the most populous state in India?', options: ['Maharashtra', 'Uttar Pradesh', 'Bihar', 'West Bengal'], correctIndex: 1, explanation: 'Uttar Pradesh was the most populous state in India according to the 2011 Census, with a population of approximately 199 million.', source: 'Census of India 2011, Registrar General of India', difficulty: 'easy' },
  { slug: 'gk-rti-act-year', categoryId: 'cat-gk', text: 'In which year was the Right to Information (RTI) Act enacted in India?', options: ['2003', '2005', '2008', '2010'], correctIndex: 1, explanation: 'The Right to Information Act was enacted on 15 June 2005. It came into full effect on 12 October 2005, empowering citizens to request information from public authorities.', source: 'Government of India, RTI Act 2005', difficulty: 'medium' },
  { slug: 'gk-aadhaar-act-year', categoryId: 'cat-gk', text: 'The Aadhaar (Targeted Delivery of Financial and Other Subsidies, Benefits and Services) Act was passed in which year?', options: ['2014', '2016', '2018', '2020'], correctIndex: 1, explanation: 'The Aadhaar Act was passed by Parliament in March 2016. It provides legal backing to the Aadhaar unique identity number system administered by UIDAI.', source: 'UIDAI, Government of India', difficulty: 'medium' },
  { slug: 'gk-gst-council-const-article', categoryId: 'cat-gk', text: 'Which Article of the Constitution was inserted by the 101st Amendment to establish the GST Council?', options: ['Article 246A', 'Article 270', 'Article 280', 'Article 315'], correctIndex: 0, explanation: 'Article 246A was inserted by the 101st Constitutional Amendment (2016) to empower Parliament and state legislatures to make laws on GST. The GST Council is established under Article 279A.', source: 'Constitution of India, 101st Amendment Act', difficulty: 'hard' },
  { slug: 'gk-hindi-official-language', categoryId: 'cat-gk', text: 'Under which Article of the Constitution is Hindi declared the official language of the Union?', options: ['Article 343', 'Article 345', 'Article 348', 'Article 351'], correctIndex: 0, explanation: 'Article 343 of the Constitution declares Hindi in Devanagari script as the official language of the Union. English was to continue for 15 years initially but has been extended indefinitely.', source: 'Constitution of India, Part XVII, Article 343', difficulty: 'medium' },

  // ═══ cat-history: Indian History (10 new) ═══
  { slug: 'hist-indus-valley-cities', categoryId: 'cat-history', text: 'Which Indus Valley Civilisation city is known for its Great Bath?', options: ['Harappa', 'Mohenjo-daro', 'Lothal', 'Kalibangan'], correctIndex: 1, explanation: 'Mohenjo-daro, located in present-day Pakistan, is famous for the Great Bath — a large waterproof tank that may have been used for ritual purification. The city dates to c. 2500 BCE.', source: 'Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'hist-buddha-birthplace', categoryId: 'cat-history', text: 'Where was Gautama Buddha born?', options: ['Bodh Gaya', 'Sarnath', 'Lumbini', 'Kushinagar'], correctIndex: 2, explanation: 'Gautama Buddha was born in Lumbini, in present-day Nepal, around 563 BCE. Lumbini is a UNESCO World Heritage Site.', source: 'UNESCO World Heritage List', difficulty: 'easy' },
  { slug: 'hist-maurya-empire-founder', categoryId: 'cat-history', text: 'Who founded the Maurya Empire in ancient India?', options: ['Ashoka', 'Chandragupta Maurya', 'Bindusara', 'Bimbisara'], correctIndex: 1, explanation: 'Chandragupta Maurya founded the Maurya Empire around 322 BCE with the guidance of Chanakya (Kautilya). It was the first empire to unify most of the Indian subcontinent.', source: 'Indian Council of Historical Research', difficulty: 'medium' },
  { slug: 'hist-gupta-empire-golden-age', categoryId: 'cat-history', text: 'The Gupta Empire (c. 320–550 CE) is often referred to as what?', options: ['The Dark Age of India', 'The Golden Age of India', 'The Buddhist Era', 'The Mauryan Revival'], correctIndex: 1, explanation: 'The Gupta Empire is called the "Golden Age of India" due to significant achievements in science, mathematics, astronomy, literature, and art. Kalidasa and Aryabhata flourished during this period.', source: 'Indian Council of Historical Research', difficulty: 'medium' },
  { slug: 'hist-battle-of-plassey', categoryId: 'cat-history', text: 'In which year did the Battle of Plassey take place?', options: ['1757', '1761', '1764', '1857'], correctIndex: 0, explanation: 'The Battle of Plassey was fought on 23 June 1757 between the British East India Company under Robert Clive and the Nawab of Bengal, Siraj-ud-Daulah. It marked the beginning of British rule in India.', source: 'National Archives of India', difficulty: 'medium' },
  { slug: 'hist-quit-india-year', categoryId: 'cat-history', text: 'In which year was the Quit India Movement launched by Mahatma Gandhi?', options: ['1930', '1935', '1942', '1945'], correctIndex: 2, explanation: 'The Quit India Movement was launched on 8 August 1942 by Mahatma Gandhi, demanding an end to British colonial rule with the slogan "Do or Die" (Karenge ya Marenge).', source: 'Gandhi Memorial Museum', difficulty: 'easy' },
  { slug: 'hist-mangal-pandey-year', categoryId: 'cat-history', text: 'Mangal Pandey\'s revolt in 1857 is associated with which event?', options: ['Non-Cooperation Movement', 'Sepoy Mutiny (First War of Independence)', 'Quit India Movement', 'Salt March'], correctIndex: 1, explanation: 'Mangal Pandey\'s revolt at Barrackpore on 29 March 1857 is considered the starting point of the Sepoy Mutiny of 1857, also known as the First War of Indian Independence.', source: 'National Archives of India', difficulty: 'medium' },
  { slug: 'hist-Partition-year', categoryId: 'cat-history', text: 'The Partition of India into India and Pakistan was announced under which plan?', options: ['Cripps Mission Plan', 'Cabinet Mission Plan', 'Mountbatten Plan', 'Wavell Plan'], correctIndex: 2, explanation: 'The Mountbatten Plan (3 June 1947) announced the partition of British India into two dominions: India and Pakistan. It was implemented on 15 August 1947.', source: 'National Archives of India', difficulty: 'hard' },
  { slug: 'hist-first-battle-panipat', categoryId: 'cat-history', text: 'The First Battle of Panipat (1526) was fought between Babur and which ruler?', options: ['Ibrahim Lodi', 'Rana Sanga', 'Humayun', 'Sher Shah Suri'], correctIndex: 0, explanation: 'The First Battle of Panipat was fought on 21 April 1526 between Babur and Ibrahim Lodi. Babur\'s victory established the Mughal Empire in India.', source: 'Indian Council of Historical Research', difficulty: 'medium' },
  { slug: 'hist-ashoka-edicts-script', categoryId: 'cat-history', text: 'In which script were most of Emperor Ashoka\'s rock edicts written?', options: ['Devanagari', 'Brahmi', 'Persian', 'Kharoshthi'], correctIndex: 1, explanation: 'Most of Ashoka\'s rock and pillar edicts were written in the Brahmi script. Some northwestern edicts were in Kharoshthi, and a few were in Greek and Aramaic.', source: 'Archaeological Survey of India', difficulty: 'hard' },

  // ═══ cat-geography: Geography (10 new) ═══
  { slug: 'geo-thar-desert-state', categoryId: 'cat-geography', text: 'The Thar Desert is primarily located in which Indian state?', options: ['Gujarat', 'Rajasthan', 'Punjab', 'Haryana'], correctIndex: 1, explanation: 'The Thar Desert (also called the Great Indian Desert) is primarily located in Rajasthan, covering about 60% of the state\'s area. It extends into parts of Gujarat, Punjab, and Haryana.', source: 'Geological Survey of India', difficulty: 'easy' },
  { slug: 'geo-western-ghats-unesco', categoryId: 'cat-geography', text: 'The Western Ghats are recognized as which type of UNESCO site?', options: ['Cultural Heritage Site', 'Natural World Heritage Site', 'Mixed Heritage Site', 'Biosphere Reserve only'], correctIndex: 1, explanation: 'The Western Ghats were inscribed as a UNESCO Natural World Heritage Site in 2012. They are one of the world\'s eight "hottest hotspots" of biological diversity.', source: 'UNESCO World Heritage List', difficulty: 'medium' },
  { slug: 'geo-brahmaputra-river-origin', categoryId: 'cat-geography', text: 'The Brahmaputra river originates in which region?', options: ['Gangotri Glacier', 'Lake Mansarovar', 'Angsi Glacier near Mount Kailash', 'Yamunotri'], correctIndex: 2, explanation: 'The Brahmaputra originates from the Angsi Glacier near Mount Kailash in Tibet. It flows through Tibet (as Yarlung Tsangpo), enters India in Arunachal Pradesh, and joins the Ganga in Bangladesh.', source: 'Survey of India / Ministry of Water Resources', difficulty: 'hard' },
  { slug: 'geo-union-territories-count-2024', categoryId: 'cat-geography', text: 'How many Union Territories does India have as of 2024?', options: ['6', '7', '8', '9'], correctIndex: 2, explanation: 'India has 8 Union Territories as of 2024: Delhi, Jammu & Kashmir, Ladakh, Puducherry, Chandigarh, Andaman & Nicobar Islands, Lakshadweep, and Dadra & Nagar Haveli and Daman & Diu.', source: 'Ministry of Home Affairs, Government of India', difficulty: 'medium' },
  { slug: 'geo-highest-dam-india', categoryId: 'cat-geography', text: 'Which is the highest dam in India?', options: ['Bhakra Dam', 'Tehri Dam', 'Hirakud Dam', 'Idukki Dam'], correctIndex: 1, explanation: 'Tehri Dam on the Bhagirathi River in Uttarakhand is the tallest dam in India at 260.5 metres (855 ft). It is a multipurpose rock and earth-fill embankment dam.', source: 'Ministry of Water Resources, Government of India', difficulty: 'medium' },
  { slug: 'geo-longest-coastline-territory', categoryId: 'cat-geography', text: 'Which Union Territory has the longest coastline in India?', options: ['Andaman and Nicobar Islands', 'Lakshadweep', 'Puducherry', 'Delhi'], correctIndex: 0, explanation: 'The Andaman and Nicobar Islands have a coastline of approximately 1,962 km, the longest among all states and Union Territories of India.', source: 'Ministry of Home Affairs', difficulty: 'hard' },
  { slug: 'geo-deccan-plateau-rivers', categoryId: 'cat-geography', text: 'Which of the following rivers flows eastward across the Deccan Plateau?', options: ['Narmada', 'Tapi', 'Godavari', 'Mahi'], correctIndex: 2, explanation: 'The Godavari flows eastward across the Deccan Plateau, draining into the Bay of Bengal. The Narmada and Tapi flow westward into the Arabian Sea through rift valleys.', source: 'Survey of India / Central Water Commission', difficulty: 'medium' },
  { slug: 'geo-cold-desert-india', categoryId: 'cat-geography', text: 'Which region in India is classified as a cold desert?', options: ['Spiti Valley in Himachal Pradesh', 'Thar Desert in Rajasthan', 'Rann of Kutch in Gujarat', 'Sundarbans in West Bengal'], correctIndex: 0, explanation: 'Spiti Valley in Himachal Pradesh (and neighboring Ladakh) is classified as a cold desert. It receives very little precipitation and experiences extremely cold winters with temperatures below -30°C.', source: 'Geological Survey of India', difficulty: 'hard' },
  { slug: 'geo-aravalli-range', categoryId: 'cat-geography', text: 'The Aravalli Range, the oldest fold mountain system in India, is located primarily in which state?', options: ['Madhya Pradesh', 'Rajasthan', 'Gujarat', 'Maharashtra'], correctIndex: 1, explanation: 'The Aravalli Range is primarily located in Rajasthan. It is the oldest fold mountain system in India, dating back to the Proterozoic era. Its highest peak is Guru Shikhar (1,722 m) at Mount Abu.', source: 'Geological Survey of India', difficulty: 'medium' },
  { slug: 'geo-sunderbans-area', categoryId: 'cat-geography', text: 'The Sundarbans delta is formed by the confluence of which rivers?', options: ['Ganga and Brahmaputra', 'Ganga and Yamuna', 'Godavari and Krishna', 'Mahanadi and Brahmani'], correctIndex: 0, explanation: 'The Sundarbans is formed by the confluence of the Ganga and Brahmaputra rivers as they empty into the Bay of Bengal. It is the world\'s largest mangrove delta and a UNESCO World Heritage Site.', source: 'UNESCO World Heritage List / Survey of India', difficulty: 'easy' },

  // ═══ cat-civics: Constitution & Civics (10 new) ═══
  { slug: 'civ-drafting-committee-chair', categoryId: 'cat-civics', text: 'Who was the Chairman of the Drafting Committee of the Indian Constitution?', options: ['Dr. Rajendra Prasad', 'Dr. B.R. Ambedkar', 'Jawaharlal Nehru', 'Sardar Patel'], correctIndex: 1, explanation: 'Dr. B.R. Ambedkar was the Chairman of the Drafting Committee of the Constituent Assembly, formed on 29 August 1947. He is widely regarded as the chief architect of the Indian Constitution.', source: 'Constitution of India / Constituent Assembly Debates', difficulty: 'easy' },
  { slug: 'civ-constituent-assembly-size', categoryId: 'cat-civics', text: 'How many members were in the Constituent Assembly that drafted the Indian Constitution?', options: ['299', '389', '500', '552'], correctIndex: 1, explanation: 'The Constituent Assembly originally had 389 members (292 from provinces, 93 from princely states, 4 from Chief Commissioners\' provinces). After partition, it was reduced to 299 members.', source: 'Constituent Assembly Debates, Parliament of India', difficulty: 'hard' },
  { slug: 'civ-fundamental-rights-count', categoryId: 'cat-civics', text: 'How many Fundamental Rights are guaranteed by the Indian Constitution?', options: ['Five', 'Six', 'Seven', 'Eight'], correctIndex: 1, explanation: 'The Constitution guarantees six Fundamental Rights: Right to Equality, Right to Freedom, Right against Exploitation, Right to Freedom of Religion, Cultural and Educational Rights, and Right to Constitutional Remedies.', source: 'Constitution of India, Part III', difficulty: 'medium' },
  { slug: 'civ-president-election-body', categoryId: 'cat-civics', text: 'The President of India is elected by which body?', options: ['Members of Parliament only', 'Members of State Legislatures only', 'An Electoral College of MPs and MLAs', 'Direct popular vote'], correctIndex: 2, explanation: 'The President is elected by an Electoral College consisting of elected members of both Houses of Parliament and the Legislative Assemblies of States and Union Territories (Delhi and Puducherry).', source: 'Constitution of India, Article 54', difficulty: 'medium' },
  { slug: 'civ-habeas-corpus-meaning', categoryId: 'cat-civics', text: 'What does the writ "Habeas Corpus" literally mean?', options: ['You shall have the body', 'By what authority', 'We command', 'To be certified'], correctIndex: 0, explanation: '"Habeas Corpus" literally means "you shall have the body". It is a writ issued by a court directing that a person detained be brought before it to determine if the detention is lawful. It is safeguarded under Article 32.', source: 'Constitution of India, Article 32', difficulty: 'medium' },
  { slug: 'civ lok-sabha-term', categoryId: 'cat-civics', text: 'What is the normal term of the Lok Sabha?', options: ['4 years', '5 years', '6 years', 'No fixed term'], correctIndex: 1, explanation: 'The Lok Sabha has a normal term of 5 years from its first meeting. It can be dissolved earlier by the President and its term can be extended during a national emergency by Parliament for up to one year at a time.', source: 'Constitution of India, Article 83', difficulty: 'easy' },
  { slug: 'civ-rajya-sabha-permanent', categoryId: 'cat-civics', text: 'Why is the Rajya Sabha called a "permanent house"?', options: ['It cannot be dissolved', 'Its members serve for life', 'It was established permanently by the Constitution', 'It meets year-round'], correctIndex: 0, explanation: 'The Rajya Sabha is called a "permanent house" because it is not subject to dissolution. One-third of its members retire every two years, and each member serves a 6-year term.', source: 'Constitution of India, Article 83', difficulty: 'medium' },
  { slug: 'civ-right-to-property', categoryId: 'cat-civics', text: 'The Right to Property was removed as a Fundamental Right by which Constitutional Amendment?', options: ['42nd Amendment', '44th Amendment', '52nd Amendment', '61st Amendment'], correctIndex: 1, explanation: 'The 44th Constitutional Amendment Act of 1978 removed the Right to Property from the list of Fundamental Rights (Article 31) and made it a legal right under Article 300A.', source: 'Constitution of India, 44th Amendment Act', difficulty: 'hard' },
  { slug: 'civ-panchayati-raj-act', categoryId: 'cat-civics', text: 'The Panchayati Raj system was given constitutional status by which Amendment?', options: ['42nd Amendment', '61st Amendment', '73rd Amendment', '86th Amendment'], correctIndex: 2, explanation: 'The 73rd Constitutional Amendment Act of 1992 gave constitutional status to Panchayati Raj institutions, adding Part IX and Articles 243 to 243-O to the Constitution.', source: 'Constitution of India, 73rd Amendment Act', difficulty: 'medium' },
  { slug: 'civ-financial-emergency-article', categoryId: 'cat-civics', text: 'Under which Article can a Financial Emergency be declared in India?', options: ['Article 352', 'Article 356', 'Article 360', 'Article 365'], correctIndex: 2, explanation: 'Article 360 of the Constitution allows the President to declare a Financial Emergency if the financial stability or credit of India is threatened. This type of emergency has never been proclaimed in India.', source: 'Constitution of India, Article 360', difficulty: 'hard' },

  // ═══ cat-science: Science & Technology (10 new) ═══
  { slug: 'sci-homi-bhabha-father', categoryId: 'cat-science', text: 'Who is widely regarded as the father of the Indian nuclear programme?', options: ['Dr. APJ Abdul Kalam', 'Dr. Homi J. Bhabha', 'Dr. Vikram Sarabhai', 'Dr. C.V. Raman'], correctIndex: 1, explanation: 'Dr. Homi Jehangir Bhabha is regarded as the father of the Indian nuclear programme. He established the Tata Institute of Fundamental Research (TIFR) in 1945 and the Atomic Energy Establishment (later renamed Bhabha Atomic Research Centre) in 1954.', source: 'Department of Atomic Energy, Government of India', difficulty: 'easy' },
  { slug: 'sci-vikram-sarabhai-father', categoryId: 'cat-science', text: 'Who is considered the father of the Indian space programme?', options: ['Dr. Homi Bhabha', 'Dr. Vikram Sarabhai', 'Dr. APJ Abdul Kalam', 'Dr. K. Kasturirangan'], correctIndex: 1, explanation: 'Dr. Vikram Sarabhai is considered the father of the Indian space programme. He founded ISRO (originally INCOSPAR) in 1962 and established the Physical Research Laboratory in Ahmedabad.', source: 'ISRO official website', difficulty: 'easy' },
  { slug: 'sci-pokhran-1-year', categoryId: 'cat-science', text: 'In which year did India conduct its first nuclear test (Pokhran-I)?', options: ['1971', '1974', '1998', '2000'], correctIndex: 1, explanation: 'India conducted its first nuclear test, codenamed "Smiling Buddha", at Pokhran on 18 May 1974. It was described as a "peaceful nuclear explosion".', source: 'Department of Atomic Energy, Government of India', difficulty: 'medium' },
  { slug: 'sci-pokhran-2-year', categoryId: 'cat-science', text: 'India\'s Pokhran-II nuclear tests were conducted in which year?', options: ['1996', '1998', '2000', '2002'], correctIndex: 1, explanation: 'Pokhran-II consisted of five nuclear tests conducted on 11 and 13 May 1998 at the Pokhran test range. This made India a declared nuclear-weapon state.', source: 'Department of Atomic Energy, Government of India', difficulty: 'medium' },
  { slug: 'sci-green-revolution-father-india', categoryId: 'cat-science', text: 'Who is considered the architect of the Green Revolution in India?', options: ['M.S. Swaminathan', 'Norman Borlaug', 'Verghese Kurien', 'Anna Hazare'], correctIndex: 0, explanation: 'Dr. M.S. Swaminathan is considered the architect of the Green Revolution in India. He developed high-yielding varieties of wheat that dramatically increased agricultural production in the 1960s.', source: 'Indian Council of Agricultural Research (ICAR)', difficulty: 'medium' },
  { slug: 'sci-white-revolution-father', categoryId: 'cat-science', text: 'Who is known as the "Father of the White Revolution" in India?', options: ['M.S. Swaminathan', 'Verghese Kurien', 'Sam Pitroda', 'Homi Bhabha'], correctIndex: 1, explanation: 'Verghese Kurien is known as the "Father of the White Revolution" in India for his role in Operation Flood, which made India the largest producer of milk in the world. He founded Amul and NDDB.', source: 'National Dairy Development Board (NDDB)', difficulty: 'easy' },
  { slug: 'sci-isa-accelerator', categoryId: 'cat-science', text: 'Where is the Large Hadron Collider (LHC), the world\'s largest particle accelerator, located?', options: ['CERN, Switzerland/France border', 'Fermilab, USA', 'KEK, Japan', 'RRCAT, India'], correctIndex: 0, explanation: 'The Large Hadron Collider is located at CERN near Geneva, on the Switzerland-France border. India is an associate member of CERN and contributed to the CMS and ALICE experiments.', source: 'CERN / Department of Atomic Energy', difficulty: 'medium' },
  { slug: 'sci-astra-missile', categoryId: 'cat-science', text: 'The Astra missile developed by DRDO is which type of missile?', options: ['Surface-to-surface ballistic', 'Air-to-air beyond visual range', 'Anti-tank guided', 'Surface-to-air'], correctIndex: 1, explanation: 'Astra is an all-weather beyond-visual-range (BVR) air-to-air missile developed by DRDO. It is the first indigenously designed BVR missile in India\'s arsenal, integrated on Sukhoi Su-30MKI aircraft.', source: 'DRDO, Ministry of Defence', difficulty: 'hard' },
  { slug: 'sci-tejas-aircraft', categoryId: 'cat-science', text: 'The HAL Tejas is which type of military aircraft?', options: ['Transport aircraft', 'Light Combat Aircraft (fighter)', 'Helicopter', 'Trainer aircraft'], correctIndex: 1, explanation: 'The HAL Tejas is an Indian single-engine, delta wing, multirole Light Combat Aircraft (LCA) designed by the Aeronautical Development Agency (ADA) and manufactured by Hindustan Aeronautics Limited (HAL).', source: 'DRDO / Ministry of Defence', difficulty: 'medium' },
  { slug: 'sci-national-science-day', categoryId: 'cat-science', text: 'National Science Day in India is observed on 28 February to commemorate which event?', options: ['ISRO\'s first satellite launch', 'Discovery of the Raman Effect', 'First nuclear test', 'Green Revolution launch'], correctIndex: 1, explanation: 'National Science Day is observed on 28 February each year to commemorate the discovery of the "Raman Effect" by Sir C.V. Raman on 28 February 1928. He was awarded the Nobel Prize for this in 1930.', source: 'Department of Science and Technology, Government of India', difficulty: 'medium' },

  // ═══ cat-sports: Sports (10 new) ═══
  { slug: 'spt-cricket-test-first', categoryId: 'cat-sports', text: 'When did India play its first Test cricket match?', options: ['1932 at Lord\'s', '1947 at Mumbai', '1952 at Delhi', '1934 at Chennai'], correctIndex: 0, explanation: 'India played its first Test match at Lord\'s Cricket Ground, London, from 25-28 June 1932 against England. India lost by 158 runs.', source: 'ESPN Cricinfo / BCCI', difficulty: 'medium' },
  { slug: 'spt-sachin-debut-year', categoryId: 'cat-sports', text: 'In which year did Sachin Tendulkar make his international cricket debut?', options: ['1987', '1989', '1991', '1993'], correctIndex: 1, explanation: 'Sachin Tendulkar made his Test debut on 15 November 1989 against Pakistan in Karachi at the age of 16 years and 205 days.', source: 'ESPN Cricinfo / BCCI', difficulty: 'easy' },
  { slug: 'spt-hockey-olympic-gold-first', categoryId: 'cat-sports', text: 'In which year did India win its first Olympic gold medal in hockey?', options: ['1920', '1928', '1932', '1936'], correctIndex: 1, explanation: 'India won its first Olympic hockey gold at the 1928 Amsterdam Olympics. India dominated Olympic hockey, winning 8 gold medals between 1928 and 1980.', source: 'International Hockey Federation (FIH) / Indian Olympic Association', difficulty: 'medium' },
  { slug: 'spt-neeraj-chopra-medal', categoryId: 'cat-sports', text: 'Neeraj Chopra won India\'s first individual Olympic gold medal in which event?', options: ['Shooting', 'Javelin Throw', 'Wrestling', 'Badminton'], correctIndex: 1, explanation: 'Neeraj Chopra won gold in the javelin throw at the Tokyo 2020 Olympics (held in 2021) with a throw of 87.58m. He was India\'s first track-and-field Olympic medalist and second individual gold medalist.', source: 'International Olympic Committee (IOC)', difficulty: 'easy' },
  { slug: 'spt-mary-kom-boxing', categoryId: 'cat-sports', text: 'How many times has Mary Kom won the World Amateur Boxing Championship?', options: ['Four times', 'Five times', 'Six times', 'Seven times'], correctIndex: 2, explanation: 'Mary Kom (Chungneijang Mary Kom Hmangte) has won the World Amateur Boxing Championship six times (2002, 2005, 2006, 2008, 2010, 2018), the most by any boxer.', source: 'International Boxing Association (AIBA)', difficulty: 'hard' },
  { slug: 'spt-ipl-first-year', categoryId: 'cat-sports', text: 'In which year was the inaugural Indian Premier League (IPL) held?', options: ['2006', '2008', '2010', '2012'], correctIndex: 1, explanation: 'The inaugural IPL was held in 2008. Rajasthan Royals, captained by Shane Warne, won the first title by defeating Chennai Super Kings in the final.', source: 'BCCI / IPL official records', difficulty: 'easy' },
  { slug: 'spt-pv-sindhu-olympic', categoryId: 'cat-sports', text: 'PV Sindhu won an Olympic silver medal in badminton at which Olympics?', options: ['London 2012', 'Rio 2016', 'Tokyo 2020', 'Paris 2024'], correctIndex: 1, explanation: 'PV Sindhu won a silver medal at the 2016 Rio Olympics in women\'s singles badminton, becoming the first Indian woman to win an Olympic silver. She also won bronze at Tokyo 2020.', source: 'International Olympic Committee (IOC) / BWF', difficulty: 'medium' },
  { slug: 'spt-viswanathan-anand-chess', categoryId: 'cat-sports', text: 'Viswanathan Anand became India\'s first Grandmaster in chess in which year?', options: ['1985', '1988', '1991', '1995'], correctIndex: 1, explanation: 'Viswanathan Anand became India\'s first chess Grandmaster in 1988 at the age of 18. He later became World Chess Champion in 2000, 2007, 2008, and 2010.', source: 'World Chess Federation (FIDE)', difficulty: 'medium' },
  { slug: 'spt-olympic-india-debut', categoryId: 'cat-sports', text: 'In which year did India first participate in the Olympic Games?', options: ['1896', '1900', '1920', '1928'], correctIndex: 1, explanation: 'India first participated in the Olympic Games in 1900 at Paris, represented by a single athlete, Norman Pritchard, who won two silver medals in athletics. India began sending official teams from 1920.', source: 'International Olympic Committee (IOC)', difficulty: 'hard' },
  { slug: 'spt-cricket-world-cup-final-2011', categoryId: 'cat-sports', text: 'Who hit the winning six for India in the 2011 Cricket World Cup final?', options: ['Sachin Tendulkar', 'MS Dhoni', 'Yuvraj Singh', 'Gautam Gambhir'], correctIndex: 1, explanation: 'MS Dhoni hit the winning six off Nuwan Kulasekara in the 2011 ICC Cricket World Cup final against Sri Lanka at Wankhede Stadium, Mumbai. India won by 6 wickets.', source: 'ICC Cricket World Cup records', difficulty: 'easy' },

  // ═══ cat-culture: Culture & Heritage (10 new) ═══
  { slug: 'cul-rath-yatra-location', categoryId: 'cat-culture', text: 'The famous Rath Yatra (chariot festival) is held annually in which city?', options: ['Varanasi', 'Puri', 'Tirupati', 'Madurai'], correctIndex: 1, explanation: 'The Rath Yatra is held annually in Puri, Odisha, at the Jagannath Temple. The festival features the procession of deities Jagannath, Balabhadra, and Subhadra on three massive chariots.', source: 'Department of Tourism, Odisha / Jagannath Temple Administration', difficulty: 'easy' },
  { slug: 'cul-kathak-origin', categoryId: 'cat-culture', text: 'The classical dance form Kathak originated in which region of India?', options: ['Tamil Nadu', 'Uttar Pradesh (North India)', 'Odisha', 'Kerala'], correctIndex: 1, explanation: 'Kathak originated in North India, particularly in Uttar Pradesh. The name derives from "kathika" (storyteller). It evolved in Hindu temples and Mughal courts, featuring intricate footwork and spins.', source: 'Sangeet Natak Akademi', difficulty: 'medium' },
  { slug: 'cul-mahabalipuram-unesco', categoryId: 'cat-culture', text: 'The Group of Monuments at Mahabalipuram are located in which state and are a UNESCO World Heritage Site since which year?', options: ['Kerala, 1995', 'Tamil Nadu, 1984', 'Karnataka, 1990', 'Andhra Pradesh, 2002'], correctIndex: 1, explanation: 'The Group of Monuments at Mahabalipuram (Mamallapuram) in Tamil Nadu were inscribed as a UNESCO World Heritage Site in 1984. They include rathas, mandapas, and rock reliefs from the Pallava dynasty (7th-8th century CE).', source: 'UNESCO World Heritage List', difficulty: 'medium' },
  { slug: 'cul-onam-boat-race', categoryId: 'cat-culture', text: 'The famous snake boat race (Vallam Kali) is associated with which festival?', options: ['Pongal', 'Onam', 'Holi', 'Dussehra'], correctIndex: 1, explanation: 'The Vallam Kali (snake boat race) is associated with Onam, the harvest festival of Kerala. The Nehru Trophy Boat Race on Punnamada Lake is the most famous.', source: 'Department of Tourism, Kerala', difficulty: 'medium' },
  { slug: 'cul-sattriya-dance-state', categoryId: 'cat-culture', text: 'The Sattriya classical dance form originates from which Indian state?', options: ['Manipur', 'Assam', 'Nagaland', 'Meghalaya'], correctIndex: 1, explanation: 'Sattriya is a classical dance form from Assam, created by the 15th-16th century Vaishnava saint Srimanta Sankardev. It was recognized as the 8th classical dance form by the Sangeet Natak Akademi in 2000.', source: 'Sangeet Natak Akademi', difficulty: 'hard' },
  { slug: 'cul-pushkar-camel-fair', categoryId: 'cat-culture', text: 'The world-famous Pushkar Camel Fair is held in which Indian state?', options: ['Gujarat', 'Rajasthan', 'Punjab', 'Haryana'], correctIndex: 1, explanation: 'The Pushkar Camel Fair (Pushkar Mela) is held annually in Pushkar, Rajasthan. It is one of the world\'s largest camel fairs, combining livestock trading with cultural festivities.', source: 'Department of Tourism, Rajasthan', difficulty: 'medium' },
  { slug: 'cul-rigveda-oldest', categoryId: 'cat-culture', text: 'The Rigveda, the oldest of the four Vedas, was composed in which language?', options: ['Pali', 'Sanskrit (Vedic)', 'Prakrit', 'Tamil'], correctIndex: 1, explanation: 'The Rigveda was composed in Vedic Sanskrit. It is one of the oldest known texts in any Indo-European language, dating to approximately 1500-1000 BCE. It contains 1,028 hymns (suktas) organized into 10 books (mandalas).', source: 'Encyclopaedia Britannica / Sahitya Akademi', difficulty: 'medium' },
  { slug: 'cul-garba-dance-state', categoryId: 'cat-culture', text: 'The Garba folk dance is traditionally associated with which Indian state?', options: ['Rajasthan', 'Gujarat', 'Maharashtra', 'Goa'], correctIndex: 1, explanation: 'Garba is a traditional dance form from Gujarat, performed during the Navratri festival. It involves circular movements around a lamp or an image of the Goddess Durga.', source: 'Sangeet Natak Akademi / Department of Tourism, Gujarat', difficulty: 'easy' },
  { slug: 'cul-bihu-festival-state', categoryId: 'cat-culture', text: 'Bihu, the most important festival of Assam, is celebrated how many times a year?', options: ['Once', 'Twice', 'Three times', 'Four times'], correctIndex: 2, explanation: 'Bihu is celebrated three times a year: Rongali (Bohag) Bihu in April (new year), Kongali (Kati) Bihu in October, and Bhogali (Magh) Bihu in January. Rongali Bihu is the most important.', source: 'Department of Tourism, Assam', difficulty: 'medium' },
  { slug: 'cul-ajanta-painting-period', categoryId: 'cat-culture', text: 'The Ajanta cave paintings primarily belong to which dynastic period(s)?', options: ['Maurya period only', 'Gupta period and Vakataka period', 'Mughal period', 'Chola period'], correctIndex: 1, explanation: 'The Ajanta cave paintings were created in two phases: the earlier Hinayana phase (2nd century BCE - 1st century CE under the Satavahanas) and the later Mahayana phase (5th-6th century CE under the Vakataka dynasty, contemporaneous with the Guptas).', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'hard' },

  // ═══ cat-economy: Economy (10 new) ═══
  { slug: 'eco-monetary-policy-committee', categoryId: 'cat-economy', text: 'The Monetary Policy Committee (MPC) of India decides which key rate?', options: ['Repo rate', 'CRR', 'SLR', 'Bank rate'], correctIndex: 0, explanation: 'The Monetary Policy Committee (MPC), established in 2016, decides the policy repo rate. It has 6 members (3 from RBI and 3 appointed by the Government) and targets inflation at 4% ±2%.', source: 'Reserve Bank of India', difficulty: 'medium' },
  { slug: 'eco-crr-meaning', categoryId: 'cat-economy', text: 'In banking, what does CRR stand for?', options: ['Cash Reserve Ratio', 'Credit Risk Ratio', 'Currency Return Rate', 'Cash Return Ratio'], correctIndex: 0, explanation: 'CRR (Cash Reserve Ratio) is the percentage of a bank\'s total deposits that it must maintain as cash reserves with the RBI. It is a tool used by the RBI to control money supply in the economy.', source: 'Reserve Bank of India', difficulty: 'medium' },
  { slug: 'eco-slr-meaning', categoryId: 'cat-economy', text: 'What does SLR stand for in Indian banking?', options: ['Statutory Liquidity Ratio', 'Standard Lending Rate', 'Secured Loan Ratio', 'Systemic Liquidity Requirement'], correctIndex: 0, explanation: 'SLR (Statutory Liquidity Ratio) is the percentage of a bank\'s net demand and time liabilities that must be maintained in liquid assets like cash, gold, or government securities.', source: 'Reserve Bank of India', difficulty: 'medium' },
  { slug: 'eco-fiscal-deficit-meaning', categoryId: 'cat-economy', text: 'What is a fiscal deficit?', options: ['Excess of revenue over expenditure', 'Excess of total expenditure over total revenue', 'Difference between imports and exports', 'Difference between tax and non-tax revenue'], correctIndex: 1, explanation: 'Fiscal deficit is the excess of a government\'s total expenditure over its total revenue (excluding borrowings). It indicates the government\'s borrowing requirement for a given financial year.', source: 'Ministry of Finance, Government of India', difficulty: 'medium' },
  { slug: 'eco-gdp-growth-rate-2024', categoryId: 'cat-economy', text: 'India became the world\'s fifth-largest economy by nominal GDP in 2022, surpassing which country?', options: ['France', 'United Kingdom', 'Germany', 'Italy'], correctIndex: 1, explanation: 'India surpassed the United Kingdom to become the world\'s fifth-largest economy by nominal GDP in 2022. India was expected to become the third-largest by 2027.', source: 'International Monetary Fund (IMF)', difficulty: 'medium' },
  { slug: 'eco-direct-tax-examples', categoryId: 'cat-economy', text: 'Which of the following is a direct tax in India?', options: ['GST', 'Customs duty', 'Income tax', 'Excise duty'], correctIndex: 2, explanation: 'Income tax is a direct tax (paid directly by the taxpayer to the government). GST, customs duty, and excise duty are indirect taxes (collected through intermediaries).', source: 'Ministry of Finance / Central Board of Direct Taxes (CBDT)', difficulty: 'easy' },
  { slug: 'eco-make-in-india-year', categoryId: 'cat-economy', text: 'The "Make in India" initiative was launched in which year?', options: ['2012', '2014', '2016', '2018'], correctIndex: 1, explanation: '"Make in India" was launched on 25 September 2014 to transform India into a global manufacturing hub. It targets 25 sectors including automobiles, textiles, and electronics.', source: 'Ministry of Commerce and Industry / Make in India portal', difficulty: 'easy' },
  { slug: 'eco-uidai-establishment', categoryId: 'cat-economy', text: 'The Unique Identification Authority of India (UIDAI) was established in which year?', options: ['2008', '2009', '2010', '2012'], correctIndex: 1, explanation: 'UIDAI was established in January 2009 as an attached office of the Planning Commission (now NITI Aayog). It issues 12-digit Aadhaar numbers to Indian residents.', source: 'UIDAI, Government of India', difficulty: 'medium' },
  { slug: 'eco-msme-definition', categoryId: 'cat-economy', text: 'In the revised MSME classification (2020), what does MSME stand for?', options: ['Micro, Small and Medium Enterprises', 'Medium, Small and Micro Entities', 'Mini, Small and Medium Establishments', 'Micro, Small and Modern Enterprises'], correctIndex: 0, explanation: 'MSME stands for Micro, Small and Medium Enterprises. The revised classification (announced in 2020) combines investment and annual turnover criteria instead of separate manufacturing/service thresholds.', source: 'Ministry of Micro, Small and Medium Enterprises', difficulty: 'easy' },
  { slug: 'eco-insolvency-bankruptcy-code', categoryId: 'cat-economy', text: 'The Insolvency and Bankruptcy Code (IBC) was enacted in which year?', options: ['2014', '2016', '2018', '2020'], correctIndex: 1, explanation: 'The Insolvency and Bankruptcy Code (IBC) was enacted in 2016 to consolidate and amend laws relating to reorganization and insolvency of corporate persons, partnership firms, and individuals.', source: 'Ministry of Finance / Insolvency and Bankruptcy Board of India (IBBI)', difficulty: 'hard' },

  // ═══ cat-environment: Environment & Wildlife (10 new) ═══
  { slug: 'env-project-elephant-year', categoryId: 'cat-environment', text: 'In which year was Project Elephant launched in India?', options: ['1982', '1992', '2002', '2010'], correctIndex: 1, explanation: 'Project Elephant was launched in 1992 by the Government of India to protect the Asian elephant and its habitat. India is home to approximately 27,000 wild elephants, the largest population in Asia.', source: 'Ministry of Environment, Forest and Climate Change', difficulty: 'medium' },
  { slug: 'env-wildlife-protection-act', categoryId: 'cat-environment', text: 'The Wildlife (Protection) Act was enacted in India in which year?', options: ['1962', '1972', '1982', '1992'], correctIndex: 1, explanation: 'The Wildlife (Protection) Act was enacted in 1972. It provides for the protection of wild animals, birds, and plants, and establishes national parks, wildlife sanctuaries, and tiger reserves.', source: 'Ministry of Environment, Forest and Climate Change', difficulty: 'medium' },
  { slug: 'env-ramsar-sites-india-count', categoryId: 'cat-environment', text: 'A Ramsar Site is a wetland of international importance. As of early 2024, approximately how many Ramsar Sites does India have?', options: ['About 25', 'About 50', 'About 75', 'About 100'], correctIndex: 2, explanation: 'As of early 2024, India has approximately 75+ Ramsar Sites, covering about 1.33 million hectares. India has the largest network of Ramsar Sites in South Asia.', source: 'Ministry of Environment, Forest and Climate Change / Ramsar Convention Secretariat', difficulty: 'hard' },
  { slug: 'env-gir-lion-state', categoryId: 'cat-environment', text: 'The Asiatic lion is found in the wild only in which Indian state?', options: ['Rajasthan', 'Gujarat', 'Madhya Pradesh', 'Maharashtra'], correctIndex: 1, explanation: 'The Asiatic lion (Panthera leo persica) is found in the wild only in Gujarat\'s Gir Forest National Park and Wildlife Sanctuary. It is one of the world\'s most endangered big cats, with about 670 individuals as of the 2020 census.', source: 'Gujarat Forest Department / IUCN Red List', difficulty: 'easy' },
  { slug: 'env-air-pollution-act', categoryId: 'cat-environment', text: 'The Air (Prevention and Control of Pollution) Act was enacted in which year?', options: ['1974', '1981', '1986', '2003'], correctIndex: 1, explanation: 'The Air (Prevention and Control of Pollution) Act was enacted in 1981 to prevent, control, and abate air pollution in India. It established Central and State Pollution Control Boards.', source: 'Ministry of Environment, Forest and Climate Change', difficulty: 'hard' },
  { slug: 'env-green-tribunal', categoryId: 'cat-environment', text: 'The National Green Tribunal (NGT) was established in which year?', options: ['2005', '2010', '2015', '2020'], correctIndex: 1, explanation: 'The National Green Tribunal was established on 18 October 2010 under the National Green Tribunal Act, 2010. It handles cases related to environmental protection and conservation of forests.', source: 'National Green Tribunal Act, 2010 / Ministry of Environment', difficulty: 'medium' },
  { slug: 'env-biodiversity-act-year', categoryId: 'cat-environment', text: 'The Biological Diversity Act was enacted in India in which year?', options: ['1999', '2002', '2006', '2012'], correctIndex: 1, explanation: 'The Biological Diversity Act was enacted in 2002 to implement the Convention on Biological Diversity. It regulates access to biological resources and benefit-sharing.', source: 'Ministry of Environment, Forest and Climate Change / National Biodiversity Authority', difficulty: 'hard' },
  { slug: 'env-namami-gange-year', categoryId: 'cat-environment', text: 'The Namami Gange programme (National Mission for Clean Ganga) was launched in which year?', options: ['2011', '2014', '2017', '2020'], correctIndex: 1, explanation: 'Namami Gange was launched in June 2014 as an Integrated Conservation Mission to accomplish the twin objectives of effective abatement of pollution and conservation of the River Ganga.', source: 'National Mission for Clean Ganga, Ministry of Jal Shakti', difficulty: 'medium' },
  { slug: 'env-india-climate-target', categoryId: 'cat-environment', text: 'India has committed to achieving net-zero carbon emissions by which year?', options: ['2040', '2050', '2070', '2100'], correctIndex: 2, explanation: 'At COP26 in Glasgow (2021), India committed to achieving net-zero carbon emissions by 2070. India also committed to installing 500 GW of non-fossil fuel energy capacity by 2030.', source: 'UNFCCC COP26 / Ministry of Environment, Forest and Climate Change', difficulty: 'medium' },
  { slug: 'env-elephant-census-method', categoryId: 'cat-environment', text: 'India\'s elephant census (synchronized elephant estimation) primarily uses which method?', options: ['Camera trapping', 'Direct sighting and dung-based estimation', 'GPS collaring', 'Aerial survey only'], correctIndex: 1, explanation: 'India\'s elephant census combines direct sighting (block count) with indirect dung-based estimation (dung decay and dung density methods). The 2017 census counted 27,312 elephants across 23 states.', source: 'Ministry of Environment, Forest and Climate Change / Project Elephant', difficulty: 'hard' },

  // ═══ cat-art: Art, Literature & Languages (10 new) ═══
  { slug: 'art-mohenjo-daro-sculpture', categoryId: 'cat-art', text: 'The "Dancing Girl" bronze sculpture was discovered at which archaeological site?', options: ['Harappa', 'Mohenjo-daro', 'Lothal', 'Kalibangan'], correctIndex: 1, explanation: 'The "Dancing Girl" bronze sculpture was discovered at Mohenjo-daro in 1926. Dating to c. 2500 BCE, it is one of the finest known Indus Valley Civilisation artworks and is displayed at the National Museum, New Delhi.', source: 'National Museum, New Delhi / Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'art-mughal-painting-origins', categoryId: 'cat-art', text: 'Mughal miniature painting flourished in India under which emperor?', options: ['Babur', 'Akbar', 'Aurangzeb', 'Sher Shah Suri'], correctIndex: 1, explanation: 'Mughal miniature painting flourished under Emperor Akbar (1556-1605). He established a royal atelier with over 100 artists, fusing Persian and Indian styles. The "Hamzanama" was a key early commission.', source: 'National Museum, New Delhi', difficulty: 'medium' },
  { slug: 'art-kalidasa-plays', categoryId: 'cat-art', text: 'Kalidasa, the greatest Sanskrit poet and dramatist, is associated with which empire?', options: ['Maurya Empire', 'Gupta Empire', 'Chola Empire', 'Vijayanagara Empire'], correctIndex: 1, explanation: 'Kalidasa is associated with the Gupta Empire (c. 4th-5th century CE). His major works include "Abhijnanasakuntalam" (The Recognition of Shakuntala), "Meghaduta", and "Raghuvamsha".', source: 'Sahitya Akademi / Encyclopaedia Britannica', difficulty: 'medium' },
  { slug: 'art-tamil-sangam-literature', categoryId: 'cat-art', text: 'Sangam literature, one of the oldest bodies of Tamil literature, was composed during approximately which period?', options: ['300 BCE - 300 CE', '500-800 CE', '1000-1200 CE', '1500-1800 CE'], correctIndex: 0, explanation: 'Sangam literature was composed roughly between 300 BCE and 300 CE in the Tamil region. It comprises about 2,381 poems by 473 poets, compiled in anthologies like Ettuthogai and Pattupattu.', source: 'Sahitya Akademi / Encyclopaedia Britannica', difficulty: 'hard' },
  { slug: 'art-hindustani-carnatic', categoryId: 'cat-art', text: 'Indian classical music is divided into which two major traditions?', options: ['Hindustani and Carnatic', 'Dhrupad and Khayal', 'Bhajan and Qawwali', 'Thumri and Tappa'], correctIndex: 0, explanation: 'Indian classical music is divided into two major traditions: Hindustani (North Indian) and Carnatic (South Indian). Both share common roots but diverged after the 12th century CE due to Persian/Islamic influences in the north.', source: 'Sangeet Natak Akademi', difficulty: 'easy' },
  { slug: 'art-rabindrasangeet', categoryId: 'cat-art', text: 'Rabindra Sangeet, a unique genre of music, consists of songs composed by whom?', options: ['Bankim Chandra Chattopadhyay', 'Rabindranath Tagore', 'Dwijendralal Ray', 'Kazi Nazrul Islam'], correctIndex: 1, explanation: 'Rabindra Sangeet consists of over 2,000 songs composed by Rabindranath Tagore. It is a distinctive genre of Bengali music that influenced Bengali culture profoundly.', source: 'Sangeet Natak Akademi / Visva-Bharati University', difficulty: 'easy' },
  { slug: 'art-tribal-art-warli', categoryId: 'cat-art', text: 'Warli painting, a tribal art form, originates from which Indian state?', options: ['Gujarat', 'Maharashtra', 'Madhya Pradesh', 'Odisha'], correctIndex: 1, explanation: 'Warli painting originates from the Warli tribe of Maharashtra, primarily in the Dahanu and Talasari regions. It is characterized by simple white geometric shapes on a red/orange background.', source: 'Ministry of Culture, Government of India', difficulty: 'medium' },
  { slug: 'art-pashupati-seal', categoryId: 'cat-art', text: 'The famous Pashupati seal, depicting a horned figure in a yogic posture, was discovered at which Indus Valley site?', options: ['Harappa', 'Mohenjo-daro', 'Dholavira', 'Rakhigarhi'], correctIndex: 1, explanation: 'The Pashupati seal was discovered at Mohenjo-daro. It depicts a seated, possibly three-faced figure surrounded by animals. The figure may represent a proto-Shiva or a deity associated with yoga.', source: 'Archaeological Survey of India / National Museum', difficulty: 'hard' },
  { slug: 'art-premchand-language', categoryId: 'cat-art', text: 'Munshi Premchand, one of India\'s greatest writers, primarily wrote in which language(s)?', options: ['Bengali only', 'Hindi and Urdu', 'Sanskrit and Hindi', 'Persian and Urdu'], correctIndex: 1, explanation: 'Munshi Premchand (1880-1936) wrote primarily in Hindi and Urdu (his earlier works were in Urdu under the name Nawab Rai). His notable works include "Godaan", "Nirmala", and short stories like "Panch Parmeshwar".', source: 'Sahitya Akademi', difficulty: 'easy' },
  { slug: 'art-bharatanatyam-bani', categoryId: 'cat-art', text: 'Bharatanatyam, a classical dance form, was historically performed by which community of temple dancers?', options: ['Nattuvanars', 'Devadasis', 'Koothambalam', 'Margi'], correctIndex: 1, explanation: 'Bharatanatyam was traditionally performed by Devadasis (women dedicated to temple deities) in Tamil Nadu. The tradition was revived and codified by Rukmini Devi Arundale, who founded Kalakshetra in 1936.', source: 'Sangeet Natak Akademi', difficulty: 'medium' },

  // ═══ cat-edu: Education (10 new) ═══
  { slug: 'edu-neet-first-exam', categoryId: 'cat-edu', text: 'NEET (National Eligibility cum Entrance Test) for medical admissions was first conducted in which year?', options: ['2010', '2013', '2016', '2018'], correctIndex: 1, explanation: 'NEET was first conducted on 5 May 2013 by the CBSE. After a Supreme Court ruling, it became the sole entrance test for MBBS/BDS admissions across India from 2016.', source: 'National Testing Agency (NTA) / Medical Council of India', difficulty: 'medium' },
  { slug: 'edu-isd-first-iit', categoryId: 'cat-edu', text: 'The Indian School of Mines (ISM) Dhanbad was established in which year?', options: ['1920', '1926', '1935', '1951'], correctIndex: 1, explanation: 'ISM Dhanbad was established in 1926. It was later converted into an IIT (IIT Dhanbad) in 2016 by an Act of Parliament.', source: 'IIT Dhanbad official website', difficulty: 'hard' },
  { slug: 'edu-allen-aiims-act', categoryId: 'cat-edu', text: 'AIIMS (All India Institute of Medical Sciences) New Delhi was established under which Act?', options: ['AIIMS Act, 1952', 'AIIMS Act, 1956', 'AIIMS Act, 1960', 'AIIMS Act, 1966'], correctIndex: 1, explanation: 'AIIMS New Delhi was established under the All India Institute of Medical Sciences Act, 1956. It was inaugurated on 17 April 1960. It has been consistently ranked as India\'s top medical institution.', source: 'AIIMS New Delhi / Ministry of Health and Family Welfare', difficulty: 'hard' },
  { slug: 'edu-iim-act-2017', categoryId: 'cat-edu', text: 'The Indian Institutes of Management (IIMs) were given the status of Institutions of National Importance by which Act?', options: ['IIM Act 2015', 'IIM Act 2017', 'IIM Act 2019', 'IIM Act 2021'], correctIndex: 1, explanation: 'The Indian Institutes of Management Act, 2017 granted the IIMs the status of Institutions of National Importance, giving them greater autonomy in academic and administrative matters.', source: 'Ministry of Education / IIM official website', difficulty: 'medium' },
  { slug: 'edu-kendriya-vidyalaya-sangathan', categoryId: 'cat-edu', text: 'The Kendriya Vidyalaya Sangathan (KVS) was established in which year?', options: ['1958', '1963', '1969', '1975'], correctIndex: 1, explanation: 'Kendriya Vidyalaya Sangathan was established on 15 December 1963. It runs central government schools (Kendriya Vidyalayas) primarily for children of transferable government employees.', source: 'Kendriya Vidyalaya Sangathan, Ministry of Education', difficulty: 'medium' },
  { slug: 'edu-national-education-policy-2020', categoryId: 'cat-edu', text: 'The National Education Policy (NEP) 2020 replaced which previous education policy?', options: ['NEP 1986 (as modified in 1992)', 'NEP 2000', 'NEP 2005', 'NEP 2010'], correctIndex: 0, explanation: 'NEP 2020 replaced the National Education Policy of 1986 (as modified in 1992). The new policy introduces a 5+3+3+4 structure and targets 50% gross enrolment ratio in higher education by 2035.', source: 'Ministry of Education, Government of India', difficulty: 'medium' },
  { slug: 'edu-upsc-const-article', categoryId: 'cat-edu', text: 'The Union Public Service Commission (UPSC) is established under which Article of the Constitution?', options: ['Article 280', 'Article 315', 'Article 324', 'Article 335'], correctIndex: 1, explanation: 'UPSC is established under Article 315 of the Constitution. It conducts examinations for appointments to the All India Services and Central Services (Group A & B).', source: 'Constitution of India, Part XIV, Article 315', difficulty: 'medium' },
  { slug: 'edu-open-university-india', categoryId: 'cat-edu', text: 'The Indira Gandhi National Open University (IGNOU), the largest open university in the world, was established in which year?', options: ['1982', '1985', '1989', '1992'], correctIndex: 1, explanation: 'IGNOU was established in 1985 by an Act of Parliament. Named after former Prime Minister Indira Gandhi, it is the world\'s largest open university with over 3 million students.', source: 'IGNOU official website / Ministry of Education', difficulty: 'medium' },
  { slug: 'edu-sarva-shiksha-abhiyan', categoryId: 'cat-edu', text: 'The Sarva Shiksha Abhiyan (SSA) was launched in which year?', options: ['1998', '2000', '2001', '2005'], correctIndex: 2, explanation: 'Sarva Shiksha Abhiyan was launched in 2001 as a flagship programme for universal elementary education. It aimed to provide education to children aged 6-14 years.', source: 'Ministry of Education, Government of India', difficulty: 'medium' },
  { slug: 'edu-scholarship-colleges-count', categoryId: 'cat-edu', text: 'Which body is responsible for granting deemed university status to institutions in India?', options: ['UGC', 'AICTE', 'NAAC', 'NITI Aayog'], correctIndex: 0, explanation: 'The University Grants Commission (UGC) grants "deemed university" status to institutions under Section 3 of the UGC Act, 1956. As of 2024, India has approximately 170+ deemed universities.', source: 'University Grants Commission (UGC)', difficulty: 'hard' },
];

async function main() {
  console.log('=== Batch 1 Import ===\n');

  const existing = await db.quizQuestion.findMany({ select: { id: true, text: true } });
  const existingTexts = existing.map((q) => q.text);
  const existingSlugs = new Set(existing.map((q) => q.id));
  console.log(`Existing questions in DB: ${existing.length}`);
  console.log(`Batch size: ${BATCH.length}\n`);

  let imported = 0, skipped = 0, rejected = 0, warned = 0;
  const rejections: Array<{ slug: string; errors: string[] }> = [];
  const warningsLog: Array<{ slug: string; warnings: string[] }> = [];

  for (const q of BATCH) {
    if (existingSlugs.has(q.slug)) { skipped++; continue; }

    // Validate
    const errors: string[] = [];
    const warnings: string[] = [];

    if (!q.text || q.text.trim().length < 10) errors.push('text too short');
    if (q.options.length !== 4) errors.push(`expected 4 options, got ${q.options.length}`);
    if (q.correctIndex < 0 || q.correctIndex >= 4) errors.push('invalid correctIndex');
    if (!q.explanation || q.explanation.trim().length < 10) errors.push('explanation too short');
    if (!q.source || q.source.trim().length < 3) errors.push('source required');
    if (!['easy', 'medium', 'hard'].includes(q.difficulty)) errors.push('invalid difficulty');

    // Duplicate check
    const dupResult = checkDuplicate(q.text, existingTexts);
    if (dupResult.isExactDuplicate) {
      errors.push(`exact duplicate: ${dupResult.reason}`);
    } else if (dupResult.isNearDuplicate) {
      warnings.push(`near-duplicate: ${dupResult.reason}`);
    }

    if (errors.length > 0) {
      rejected++;
      rejections.push({ slug: q.slug, errors });
      continue;
    }

    if (warnings.length > 0) {
      warned++;
      warningsLog.push({ slug: q.slug, warnings });
    }

    // Build options array
    const options = q.options.map((text, i) => ({ id: String.fromCharCode(97 + i), text }));
    const correctOptionId = options[q.correctIndex].id;
    const correctIndex = q.correctIndex;

    try {
      await db.quizQuestion.create({
        data: {
          id: q.slug,
          categoryId: q.categoryId,
          text: q.text.trim(),
          translations: '{}',
          options: JSON.stringify(options),
          correctOptionIndex: correctIndex,
          explanation: q.explanation.trim(),
          explanationTranslations: '{}',
          source: q.source.trim(),
          difficulty: q.difficulty,
          language: 'en',
          published: true,
        },
      });
      existingTexts.push(q.text);
      imported++;
    } catch (e) {
      rejected++;
      rejections.push({ slug: q.slug, errors: [(e as Error).message] });
    }
  }

  console.log(`\n=== Import Summary ===`);
  console.log(`  Imported: ${imported}`);
  console.log(`  Skipped (already existed): ${skipped}`);
  console.log(`  Rejected: ${rejected}`);
  console.log(`  Warnings (near-dup, still imported): ${warned}`);

  if (rejections.length > 0) {
    console.log(`\n  --- Rejected ---`);
    for (const r of rejections) console.log(`  [${r.slug}] ${r.errors.join('; ')}`);
  }
  if (warningsLog.length > 0) {
    console.log(`\n  --- Near-duplicate warnings ---`);
    for (const w of warningsLog) console.log(`  [${w.slug}] ${w.warnings.join('; ')}`);
  }

  // Count by category
  console.log(`\n=== Post-import counts ===`);
  const allCats = ['cat-gk','cat-history','cat-geography','cat-civics','cat-science','cat-sports','cat-culture','cat-economy','cat-environment','cat-art','cat-edu'];
  let total = 0;
  for (const cat of allCats) {
    const c = await db.quizQuestion.count({ where: { categoryId: cat } });
    if (c > 0) console.log(`  ${cat}: ${c}`);
    total += c;
  }
  console.log(`  TOTAL: ${total}`);
}

main().then(() => process.exit(0));
